-- Disposable adult test evidence only. No physical verification or live participation.
insert into public.academic_subjects(id,grade_id,name,is_published) values ('maharashtra-8-mathematics','maharashtra-8','Mathematics',true);
update auth.users set email_confirmed_at=now() where email like 'vv-test-%@example.invalid';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English')->'candidates')=0,'no invented tutors when no eligible opt-ins');
select pg_temp.expect_error($q$select public.discover_test_tutors('missing','English')$q$,'22023','unknown subject rejected');
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics',null)$q$,'22023','missing language rejected');
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics','English',repeat('x',65))$q$,'22023','search bounded');
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics','English','',1::smallint,'17:00'::time,'16:00'::time)$q$,'22023','invalid time window rejected');
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics','English','',null,'16:00'::time,null)$q$,'22023','partial time window rejected');
select pg_temp.expect_error($q$select public.set_tutor_discovery_preview(true,1)$q$,'42501','learner cannot opt a tutor in');
select pg_temp.expect_error($q$select private.evaluate_tutor_match(true,true,'approved',12::smallint,12::smallint,true,true,100,true,8::smallint)$q$,'42501','private evaluator not callable by client');
reset role;
update public.tutor_profiles set discovery_preview_enabled=true,discovery_preview_id='90000000-0000-0000-0000-000000000003',teaching_skill_score=75 where user_id='00000000-0000-0000-0000-000000000003';
insert into public.tutor_verification_records(tutor_id,status,reviewed_by,verified_grade,decision_note) values
 ('00000000-0000-0000-0000-000000000003','approved','00000000-0000-0000-0000-000000000005',10,'LOCAL TEST ONLY: private evidence must never leave discovery.');
update public.tutor_availability set enabled=true where tutor_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
create temporary table discovery_result as select public.discover_test_tutors('cbse-8-mathematics','English','',1::smallint,'16:00'::time,'17:00'::time) as result;
select pg_temp.assert_true((select result->>'test_only'='true' and result->>'availability_basis'='requested_weekly_window' from discovery_result),'test-only envelope and time basis');
select pg_temp.assert_true((select jsonb_array_length(result->'candidates')=1 and (result#>>'{candidates,0,cms}')::numeric=95 from discovery_result),'real qualified candidate and exact CMS');
select pg_temp.assert_true((select result#>>'{candidates,0,label}'='Test tutor 90000000' and result#>>'{candidates,0,preview_id}'<>'00000000-0000-0000-0000-000000000003' from discovery_result),'opaque pseudonym rather than account identity');
select pg_temp.assert_true((select (select count(*) from jsonb_object_keys(result#>'{candidates,0}'))=10 from discovery_result),'exact privacy-safe field projection');
select pg_temp.assert_true((select result::text not like '%private evidence%' and result::text not like '%example.invalid%' and result::text not like '%16:00%' and result::text not like '%reviewed_by%' and result::text not like '%tutor_id%' from discovery_result),'no private notes, emails, schedules or account IDs');
select pg_temp.assert_true((select count(*)=0 from public.tutor_profiles),'discovery does not widen private tutor table access');
select pg_temp.assert_true((select count(*)=0 from public.tutor_availability),'discovery does not widen schedule RLS');
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','हिन्दी')->'candidates')=0,'language qualification required');
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-6-mathematics','English')->'candidates')=0,'exact grade-specific subject qualification required');
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('maharashtra-8-mathematics','English')->'candidates')=0,'board-specific qualification required');
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-7-science','English')->'candidates')=0,'subject qualification required');
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English','example.invalid')->'candidates')=0,'search cannot query private identities');
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English','',1::smallint,'17:00'::time,'18:00'::time,true)->'candidates')=0,'weekly window requires full coverage; end is exclusive');
select pg_temp.assert_true((public.discover_test_tutors('cbse-8-mathematics','English','',1::smallint,'17:00'::time,'18:00'::time)#>>'{candidates,0,cms}')::numeric=80,'otherwise eligible candidate remains ranked without matching preference');
reset role;
-- Re-evaluation uses latest records rather than a frontend eligibility cache.
update public.tutor_profiles set teaching_skill_score=49.99 where user_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English')->'candidates')=0,'TSS below 50 excluded');
reset role;
update public.tutor_profiles set teaching_skill_score=50 where user_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English')->'candidates')=1,'TSS exactly 50 eligible');
reset role;
insert into public.tutor_verification_records(tutor_id,status,reviewed_by,decision_note) values
 ('00000000-0000-0000-0000-000000000003','revoked','00000000-0000-0000-0000-000000000005','LOCAL TEST ONLY: revoked');
set local role authenticated;
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English')->'candidates')=0,'latest revocation overrides older approval');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","session_id":"00000000-0000-0000-0000-000000000003"}',true);
select public.set_tutor_discovery_preview(false,(select revision from public.tutor_profiles));
select pg_temp.assert_true((select not discovery_preview_enabled from public.tutor_profiles),'tutor can persist opt-out but not grant eligibility');
select pg_temp.expect_error($q$select public.set_tutor_discovery_preview(true,1)$q$,'40001','stale preview preference rejected');
select pg_temp.expect_error($q$update public.tutor_profiles set discovery_preview_enabled=true$q$,'42501','direct opt-in update bypass denied');
select pg_temp.expect_error($q$update public.tutor_profiles set discovery_preview_id=gen_random_uuid()$q$,'42501','public pseudonym cannot be forged');
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics','English')$q$,'42501','tutor-only role cannot discover others');
reset role;
-- Non-learner roles never acquire directory privileges by virtue of their name.
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000006","session_id":"00000000-0000-0000-0000-000000000006"}',true);
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics','English')$q$,'42501','app admin cannot bypass discovery gate');
reset role;
delete from auth.sessions where user_id='00000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics','English')$q$,'42501','revoked learner session denied');
reset role;
set local role anon;
select pg_temp.expect_error($q$select public.discover_test_tutors('cbse-8-mathematics','English')$q$,'42501','anonymous discovery denied');
select pg_temp.expect_error($q$select public.set_tutor_discovery_preview(true,1)$q$,'42501','anonymous opt-in denied');
reset role;
